/* ---------- utilidades ---------- */
const col=k=>{const t=T();return t[k]||(t[k]=[])};
const NIV0=['Inicial','En desarrollo','Competente','Avanzado','Referente'];
const cfg=()=>{const t=T();return t.de_cfg||(t.de_cfg={niveles:NIV0.slice(),lmsCats:['Inducción','Cumplimiento','Seguridad y salud','Herramientas','Liderazgo','Tecnología','Comercial']})};
const acts=()=>T().relaciones.filter(r=>r.estado==='Activo');
const rel=id=>T().relaciones.find(r=>r.id===id);
const mine=()=>{const r=myRel();return r?r.id:''};
const scIds=()=>scoped().map(r=>r.id);
const inSc=id=>scoped().some(r=>r.id===id);
const avg=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
const sum=a=>a.reduce((s,x)=>s+(+x||0),0);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const n1=v=>v?(+v).toFixed(1):'—';
const sn=id=>{const r=rel(id);if(!r)return'—';const p=per(r);return p.nombres.split(' ')[0]+' '+p.apellidos.split(' ')[0]};
const wc=id=>{const r=rel(id);return r?whoCell(r):'<span class="muted">—</span>'};
const puesto=id=>(get('puestos',id)||{nombre:'—',nivel:''});
const chip=(id,a)=>{const r=rel(id);if(!r)return'';return `<${a?'button':'span'} class="de-chip"${a?` data-a="${a}" data-id="${id}"`:''} title="${esc(nm(r))}"><span class="av">${esc(ini(nm(r)))}</span>${esc(sn(id))}</${a?'button':'span'}>`};
const prog=(p,k)=>`<div class="bar" role="img" aria-label="${Math.round(p)} %"><i style="width:${clamp(p,0,100)}%${k?`;background:var(--${k})`:''}"></i></div>`;
const tabsH=(k,items)=>`<div class="tabs" style="padding:0 8px">${items.map(t=>`<button class="tab ${ui[k]===t[0]?'on':''}" data-a="de_tab" data-k="${k}" data-v="${t[0]}">${t[1]}</button>`).join('')}</div>`;
const selH=(k,opts,first,lab)=>`<select class="in" id="${k}" data-c="${k}" style="width:auto;max-width:100%" aria-label="${esc(lab||first||'Filtro')}">${first?`<option value="">${esc(first)}</option>`:''}${opts.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${esc(a[0])}"${String(ui[k])===String(a[0])?' selected':''}>${esc(a[1])}</option>`}).join('')}</select>`;
const deny=()=>`<div class="panel">${emptyState('No tienes acceso a esta pantalla','Tu rol no incluye el permiso necesario. Si lo necesitas, pídelo a quien administra los roles.','<button class="btn" data-a="nav" data-r="inicio">Volver al inicio</button>')}</div>`;
const gone=(r,l,t)=>`<div class="panel">${emptyState(t,'Puede que se haya eliminado o que esté fuera de tu alcance.',`<button class="btn" data-a="nav" data-r="${r}">Volver a ${esc(l)}</button>`)}</div>`;
const crumbs=(r,l,cur)=>`<div class="crumb"><a href="#" data-a="nav" data-r="${r}">${esc(l)}</a> / ${esc(cur)}</div>`;
const kpi=(v,l,k)=>`<div class="kpi"><b class="num"${k?` style="color:var(--${k})"`:''}>${v}</b><span>${l}</span></div>`;
const lines=s=>String(s||'').split('\n').map(x=>x.trim()).filter(Boolean);
const paras=s=>lines(s).map(x=>`<p>${esc(x)}</p>`).join('');
const uniTop=r=>{const u=uniOf(r);return u?u.id:''};
const inUni=(r,uid)=>{let u=uniOf(r),n=0;while(u&&n++<20){if(u.id===uid)return true;u=get('unidades',u.padreId)}return false};
const csvModal=(title,rows,what)=>{const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',txt=rows.map(r=>r.map(q).join(',')).join('\n');log('Exportación',what,(rows.length-1)+' filas','','','CSV');save();
 openModal(title,`<div style="display:flex;flex-direction:column;gap:10px"><p class="muted">Respeta tus filtros y permisos. Copia el contenido y pégalo en Excel o guárdalo como archivo .csv.</p><textarea class="in mono" id="csvt" rows="10" readonly>${esc(txt)}</textarea></div>`,'<button class="btn" data-a="closeM">Cerrar</button><button class="btn p" data-a="copyCsv">Copiar</button>')};
const simMsg=(para,asunto)=>{col('de_mensajes').unshift({id:nid('dm'),fecha:new Date().toISOString(),para,asunto,por:me().nombre})};
const lvl=(n)=>n?(cfg().niveles[n-1]||'Nivel '+n):'Sin evaluar';

/* =====================================================================
   DESEMPEÑO · 1. Campañas de evaluación
   ===================================================================== */
const TIPOS={'90°':['Jefe'],'180°':['Autoevaluación','Jefe'],'270°':['Autoevaluación','Jefe','Par'],'360°':['Autoevaluación','Jefe','Par','Subordinado']};
const TL={Autoevaluación:'Autoevaluación',Jefe:'Jefe directo',Par:'Par',Subordinado:'Reporte directo'};
const TDESC={'90°':'Solo evalúa el jefe directo.','180°':'Autoevaluación y jefe directo.','270°':'Autoevaluación, jefe directo y pares.','360°':'Autoevaluación, jefe directo, pares y reportes directos.'};
const ESC={5:['Muy por debajo de lo esperado','Por debajo de lo esperado','Cumple lo esperado','Supera lo esperado','Excepcional'],4:['Por debajo de lo esperado','Cumple parcialmente','Cumple lo esperado','Supera lo esperado'],3:['Por debajo de lo esperado','Cumple lo esperado','Supera lo esperado']};
const POT=['','Bajo','Medio','Alto'];
const ciclo=id=>col('evalCiclos').find(c=>c.id===id);
const formOf=id=>col('de_evalForms').find(f=>f.id===id);
const formsDe=cid=>col('de_evalForms').filter(f=>f.cicloId===cid);
const fVenc=f=>f.estado!=='Enviada'&&f.vence<TODAY;
const fScore=(f,c)=>{const v=c.competencias.map(k=>f.resp[k]).filter(Boolean);return v.length?avg(v)/c.escala.length*5:0};
const comp=id=>col('de_comps').find(c=>c.id===id)||{nombre:'(competencia eliminada)',desc:'',tipo:''};
function calc(ev){const c=ciclo(ev.cicloId),fs=col('de_evalForms').filter(f=>f.evalId===ev.id&&f.estado==='Enviada'),por={};
 fs.forEach(f=>(por[f.tipo]=por[f.tipo]||[]).push(fScore(f,c)));
 let s=0,w=0;Object.keys(por).forEach(k=>{por[k]=avg(por[k]);const p=+c.pesos[k]||0;s+=por[k]*p;w+=p});
 return{nota:w?s/w:(Object.keys(por).length?avg(Object.values(por)):0),por,n:fs.length}}
function syncEval(ev){if(!ev||['Calibrada','Publicada'].includes(ev.estado))return;const fs=col('de_evalForms').filter(f=>f.evalId===ev.id),n=fs.filter(f=>f.estado==='Enviada').length;
 ev.estado=fs.length&&n===fs.length?'Completada':(n||fs.some(f=>f.estado==='Borrador'))?'En curso':'Pendiente'}
function asignar(c){const out=[],ac=acts(),ts=TIPOS[c.tipo];
 c.participantes.forEach(id=>{const r=rel(id);if(!r||r.estado!=='Activo')return;
  if(ts.includes('Autoevaluación'))out.push({relId:id,evaluadorId:id,tipo:'Autoevaluación'});
  const j=r.jefeId&&rel(r.jefeId);
  if(ts.includes('Jefe')&&j&&j.estado==='Activo')out.push({relId:id,evaluadorId:j.id,tipo:'Jefe'});
  if(ts.includes('Par')&&r.jefeId)ac.filter(x=>x.jefeId===r.jefeId&&x.id!==id).slice(0,+c.maxPares||2).forEach(x=>out.push({relId:id,evaluadorId:x.id,tipo:'Par'}));
  if(ts.includes('Subordinado'))ac.filter(x=>x.jefeId===id).slice(0,+c.maxSub||3).forEach(x=>out.push({relId:id,evaluadorId:x.id,tipo:'Subordinado'}))});
 return out}
const notaPill=v=>v?`<span class="pill ${v>=4?'ok':v>=3?'acc':'warn'} num">${n1(v)}</span>`:'<span class="muted">—</span>';
const cEstPill=c=>pill(c.estado,{Borrador:'','En curso':'acc',Calibración:'warn',Publicado:'ok'}[c.estado]);
const fEstPill=f=>fVenc(f)?pill('Vencida','crit'):pill(f.estado==='Borrador'?'En borrador':f.estado,f.estado==='Enviada'?'ok':f.estado==='Borrador'?'acc':'warn');
const misForms=()=>{const m=mine();return m?col('de_evalForms').filter(f=>f.evaluadorId===m&&f.estado!=='Enviada'&&(ciclo(f.cicloId)||{}).estado==='En curso'):[]};
const seeCamp=()=>can('desempeno.campanas.administrar')||can('desempeno.calibrar')||(can('desempeno.resultados.ver')&&role().alcance!=='propio');
function canSeeRes(ev){const c=ciclo(ev.cicloId);if(!c)return false;if(ev.relId===mine())return c.estado==='Publicado'&&ev.estado==='Publicada';
 if(can('desempeno.calibrar'))return inSc(ev.relId);return can('desempeno.resultados.ver')&&inSc(ev.relId)&&c.estado==='Publicado'}

function vEval(){const my=mine(),sc=seeCamp();
 const tabs=[...(my&&can('desempeno.ver')?[['mias','Mis evaluaciones']]:[]),...(sc?[['camp','Campañas']]:[])];
 if(!tabs.length)return deny();if(!tabs.some(t=>t[0]===ui.de_evTab))ui.de_evTab=tabs[0][0];
 let b='';
 if(ui.de_evTab==='mias'){const pend=misForms().sort((a,b)=>a.vence.localeCompare(b.vence)),sent=col('de_evalForms').filter(f=>f.evaluadorId===my&&f.estado==='Enviada').sort((a,b)=>(b.enviada||'').localeCompare(a.enviada||'')).slice(0,12);
  const evs=col('evaluaciones').filter(e=>e.relId===my).sort((a,b)=>(ciclo(b.cicloId)||{}).hasta>(ciclo(a.cicloId)||{}).hasta?1:-1);
  const row=f=>{const c=ciclo(f.cicloId)||{},d=days(TODAY,f.vence);return `<tr><td>${wc(f.relId)}</td><td>${pill(TL[f.tipo],f.tipo==='Autoevaluación'?'acc':'')}</td><td>${esc(c.nombre)}</td><td class="num">${f.estado==='Enviada'?fd(f.enviada):fd(f.vence)+(d<0?` <span class="pill crit">hace ${-d} d</span>`:d<=5?` <span class="pill warn">en ${d} d</span>`:'')}</td><td>${fEstPill(f)}</td><td style="text-align:right"><button class="btn s ${f.estado==='Enviada'?'':'p'}" data-a="de_formOpen" data-id="${f.id}">${f.estado==='Enviada'?'Ver':f.estado==='Borrador'?'Continuar':'Responder'}</button></td></tr>`};
  b=`<div class="ph"><h2>Por responder</h2><span class="pill ${pend.length?'warn':'ok'}">${pend.length}</span></div>
  ${pend.length?`<div class="tw"><table class="de-t"><thead><tr><th>Evalúas a</th><th>Tu rol</th><th>Campaña</th><th>Vence</th><th>Estado</th><th></th></tr></thead><tbody>${pend.map(row).join('')}</tbody></table></div>`:emptyState('No tienes evaluaciones por responder','Cuando Recursos Humanos lance una campaña en la que participes, tus formularios aparecerán aquí.')}
  <div class="ph" style="border-top:1px solid var(--line)"><h2>Mis resultados</h2></div>
  ${evs.length?`<div class="tw"><table class="de-t"><thead><tr><th>Campaña</th><th>Periodo</th><th>Resultado</th><th></th></tr></thead><tbody>${evs.map(e=>{const c=ciclo(e.cicloId)||{},pub=c.estado==='Publicado'&&e.estado==='Publicada';return `<tr><td><b>${esc(c.nombre)}</b><div class="muted">Evaluación ${esc(c.tipo)}</div></td><td class="num">${fd(c.desde)} – ${fd(c.hasta)}</td><td>${pub?notaPill(e.nota)+' <span class="muted">de 5</span>':'<span class="muted">Aún no se publica. Lo verás cuando RRHH termine la calibración.</span>'}</td><td style="text-align:right">${pub?`<button class="btn s" data-a="de_resOpen" data-id="${e.id}">Ver resultado</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="pb muted">Todavía no has sido evaluado en ninguna campaña.</div>'}
  ${sent.length?`<details style="border-top:1px solid var(--line)"><summary class="de-sum"><h3>Evaluaciones que ya enviaste (${sent.length})</h3></summary><div class="tw"><table class="de-t"><tbody>${sent.map(row).join('')}</tbody></table></div></details>`:''}`}
 else{const cs=col('evalCiclos').slice().sort((a,b)=>b.hasta.localeCompare(a.hasta)),ids=scIds();
  b=cs.length?`<div class="tw"><table class="de-t"><thead><tr><th>Campaña</th><th>Tipo</th><th>Periodo</th><th>Participantes</th><th style="min-width:150px">Formularios enviados</th><th>Estado</th></tr></thead><tbody>${cs.map(c=>{const fs=formsDe(c.id).filter(f=>ids.includes(f.relId)),n=fs.filter(f=>f.estado==='Enviada').length,p=fs.length?n/fs.length*100:0;return `<tr class="click" data-a="de_cicloOpen" data-id="${c.id}"><td><b>${esc(c.nombre)}</b></td><td>${pill(c.tipo)}</td><td class="num">${fd(c.desde)} – ${fd(c.hasta)}</td><td class="num">${c.participantes.filter(x=>ids.includes(x)).length}</td><td>${fs.length?`<div class="row" style="flex-wrap:nowrap"><div style="flex:1">${prog(p)}</div><span class="num muted">${n}/${fs.length}</span></div>`:'<span class="muted">Sin lanzar</span>'}</td><td>${cEstPill(c)}</td></tr>`}).join('')}</tbody></table></div>`
  :emptyState('Aún no hay campañas de evaluación','Crea la primera: eliges el tipo (90°, 180°, 270° o 360°), las competencias y a quiénes se evalúa. Los evaluadores se asignan solos según la jerarquía.',can('desempeno.campanas.administrar')?'<button class="btn p" data-a="de_cicloNew">Nueva campaña</button>':'')}
 return pageHead('Talento','Evaluaciones de desempeño',sc&&can('desempeno.campanas.administrar')?'<button class="btn p" data-a="de_cicloNew">Nueva campaña</button>':'')+`<div class="panel">${tabs.length>1?tabsH('de_evTab',tabs):''}${b}</div>`}

function formCiclo(id){const c=id?ciclo(id):null;
 openForm(v=>{const k=+v.esc||5;return{title:c?'Editar campaña':'Nueva campaña de evaluación',ok:c?'Guardar':'Crear en borrador',
  note:'<b>'+esc(v.tipo)+':</b> '+TDESC[v.tipo]+' Los evaluadores se asignan automáticamente con la jerarquía vigente al lanzar la campaña; luego puedes ajustarlos.',
  fields:[{k:'nombre',l:'Nombre de la campaña',req:1,full:1},{k:'tipo',l:'Tipo de evaluación',opts:Object.keys(TIPOS),req:1,dyn:1},{k:'esc',l:'Escala',opts:[[5,'5 puntos'],[4,'4 puntos'],[3,'3 puntos']],req:1,dyn:1},
   {k:'desde',l:'Inicio',type:'date',req:1},{k:'hasta',l:'Fecha límite para responder',type:'date',req:1},
   {k:'competencias',l:'Competencias que se evalúan',type:'checks',opts:col('de_comps').filter(x=>x.activo!==false&&x.tipo==='Competencia').map(x=>[x.id,x.nombre]),req:1,full:1},
   {k:'escala',l:'Etiquetas de la escala (una por línea, de menor a mayor)',type:'textarea',full:1},
   {k:'preguntas',l:'Preguntas abiertas (una por línea)',type:'textarea',full:1},
   ...TIPOS[v.tipo].map(t=>({k:'w_'+t,l:'Peso de «'+TL[t]+'» en la nota (%)',type:'number'})),
   {k:'alc',l:'A quiénes se evalúa',opts:[['todos','Toda la organización'],['empresa','Una empresa'],['unidad','Un área o equipo'],['manual','Selección manual']],req:1,dyn:1},
   ...(v.alc==='empresa'?[{k:'empresaId',l:'Empresa',opts:opt('empresas'),req:1}]:v.alc==='unidad'?[{k:'unidadId',l:'Área o equipo (incluye sus subunidades)',opts:opt('unidades'),req:1}]:v.alc==='manual'?[{k:'sel',l:'Personas',type:'checks',opts:acts().map(r=>[r.id,nm(r)]),req:1,full:1}]:[])],
  submit:o=>{if(o.hasta<=o.desde)return 'La fecha límite debe ser posterior al inicio.';
   const el=lines(o.escala);if(el.length&&el.length!==k)return 'La escala es de '+k+' puntos: escribe exactamente '+k+' etiquetas (o deja el campo vacío para usar las sugeridas).';
   const ts=TIPOS[o.tipo],pesos={};ts.forEach(t=>pesos[t]=+o['w_'+t]||0);if(!sum(Object.values(pesos)))return 'Al menos un tipo de evaluador debe tener peso mayor a cero.';
   const part=acts().filter(r=>o.alc==='todos'||(o.alc==='empresa'&&r.empresaId===o.empresaId)||(o.alc==='unidad'&&inUni(r,o.unidadId))||(o.alc==='manual'&&o.sel.includes(r.id))).map(r=>r.id);
   if(!part.length)return 'Con ese criterio no hay personas activas que evaluar.';
   const d={nombre:o.nombre,tipo:o.tipo,desde:o.desde,hasta:o.hasta,competencias:o.competencias,escala:el.length?el:ESC[k].slice(),preguntas:lines(o.preguntas).map((t,i)=>({id:'q'+(i+1),texto:t})),pesos,participantes:part,alc:o.alc,empresaId:o.empresaId||'',unidadId:o.unidadId||''};
   if(c){Object.assign(c,d);log('Edición','Campaña de evaluación',c.nombre,c.id,'',o.tipo+' · '+part.length+' participantes')}
   else{const n={id:nid('dci'),estado:'Borrador',creada:TODAY,maxPares:2,maxSub:3,recordatorios:[],...d};col('evalCiclos').push(n);log('Alta','Campaña de evaluación',n.nombre,n.id,'',o.tipo+' · '+part.length+' participantes');ui.de_ciclo=n.id;ui.de_cTab='config';ui.route='de_ciclo'}
   toast('Campaña guardada')}}},
  c?{nombre:c.nombre,tipo:c.tipo,esc:c.escala.length,desde:c.desde,hasta:c.hasta,competencias:c.competencias,escala:c.escala.join('\n'),preguntas:c.preguntas.map(q=>q.texto).join('\n'),alc:c.alc||'manual',empresaId:c.empresaId,unidadId:c.unidadId,sel:c.participantes,...Object.fromEntries(Object.entries(c.pesos).map(([k,v])=>['w_'+k,v]))}
  :{tipo:'180°',esc:5,desde:TODAY,hasta:addDays(TODAY,21),alc:'todos',competencias:col('de_comps').filter(x=>x.activo!==false&&x.tipo==='Competencia').slice(0,4).map(x=>x.id),preguntas:'¿Cuál fue su principal logro del periodo?\n¿Qué debería mejorar o empezar a hacer?',w_Autoevaluación:20,w_Jefe:50,w_Par:20,w_Subordinado:10})}

function vCiclo(){const c=ciclo(ui.de_ciclo);if(!c)return gone('de_eval','Evaluaciones','La campaña ya no existe');if(!seeCamp())return deny();
 const adm=can('desempeno.campanas.administrar'),cal=can('desempeno.calibrar'),ids=scIds(),pot=cal||can('talento.ninebox.ver');
 const fs=formsDe(c.id).filter(f=>ids.includes(f.relId)),evs=col('evaluaciones').filter(e=>e.cicloId===c.id&&ids.includes(e.relId)).sort((a,b)=>relName(a.relId).localeCompare(relName(b.relId),'es'));
 const ts=TIPOS[c.tipo],sent=fs.filter(f=>f.estado==='Enviada').length,venc=fs.filter(fVenc).length;
 const tabs=[['avance','Avance'],['part','Evaluadores'],['config','Configuración'],['calib','Calibración y resultados']];if(!tabs.some(t=>t[0]===ui.de_cTab))ui.de_cTab='avance';
 let acc='';
 if(adm&&c.estado==='Borrador')acc=`<button class="btn d" data-a="de_cicloDel" data-id="${c.id}">Eliminar</button><button class="btn" data-a="de_cicloEdit" data-id="${c.id}">Editar</button><button class="btn p" data-a="de_cicloLanzar" data-id="${c.id}">Lanzar campaña</button>`;
 if(adm&&c.estado==='En curso')acc=`<button class="btn" data-a="de_cicloRec" data-id="${c.id}">Enviar recordatorio</button><button class="btn p" data-a="de_cicloCerrar" data-id="${c.id}">Cerrar y calibrar</button>`;
 if(c.estado==='Calibración')acc=(adm?`<button class="btn" data-a="de_cicloReabrir" data-id="${c.id}">Reabrir recolección</button>`:'')+(cal?`<button class="btn p" data-a="de_cicloPub" data-id="${c.id}">Publicar resultados</button>`:'');
 if(c.estado==='Publicado'&&can('datos.exportar')&&cal)acc=`<button class="btn" data-a="de_cicloCsv" data-id="${c.id}">Exportar resultados</button>`;
 let b='';
 if(ui.de_cTab==='avance'){
  if(c.estado==='Borrador'){const pv=asignar(c);b=`<div class="pb">${emptyState('La campaña todavía no se lanza',`Al lanzarla se crearán <b>${pv.length}</b> formularios para <b>${c.participantes.length}</b> personas (${ts.map(t=>pv.filter(x=>x.tipo===t).length+' de '+TL[t].toLowerCase()).join(', ')}). Revisa la configuración antes de lanzar.`,adm?`<button class="btn p" data-a="de_cicloLanzar" data-id="${c.id}">Lanzar campaña</button>`:'')}</div>`}
  else b=`<div class="pb" style="display:flex;flex-direction:column;gap:16px"><div class="grid g4">${ts.map(t=>{const x=fs.filter(f=>f.tipo===t),n=x.filter(f=>f.estado==='Enviada').length;return `<div><div class="de-kv"><span>${TL[t]}</span><b class="num">${n}/${x.length}</b></div>${prog(x.length?n/x.length*100:0)}</div>`}).join('')}</div>
   ${(c.recordatorios||[]).length?`<div class="note">Recordatorios enviados (simulado, no sale ningún correo real): ${c.recordatorios.map(r=>`${fd(r.fecha)} a ${r.n} persona${r.n===1?'':'s'}`).join(' · ')}</div>`:''}</div>
   <div class="tw"><table class="de-t"><thead><tr><th>Evaluado</th>${ts.map(t=>`<th>${TL[t]}</th>`).join('')}<th style="min-width:130px">Avance</th><th>Estado</th></tr></thead><tbody>${evs.map(e=>{const x=fs.filter(f=>f.evalId===e.id),n=x.filter(f=>f.estado==='Enviada').length;return `<tr><td>${wc(e.relId)}</td>${ts.map(t=>{const y=x.filter(f=>f.tipo===t),k=y.filter(f=>f.estado==='Enviada').length;return `<td>${y.length?`<span class="pill ${k===y.length?'ok':y.some(fVenc)?'crit':k||y.some(f=>f.estado==='Borrador')?'acc':''} num">${k}/${y.length}</span>`:'<span class="muted">—</span>'}</td>`}).join('')}<td>${prog(x.length?n/x.length*100:0)}</td><td>${pill(e.estado,e.estado==='Publicada'||e.estado==='Completada'?'ok':e.estado==='Calibrada'?'acc':e.estado==='Pendiente'?'warn':'')}</td></tr>`}).join('')}</tbody></table></div>`}
 if(ui.de_cTab==='part'){
  if(c.estado==='Borrador'){const pv=asignar(c);b=`<div class="pb"><div class="note">Vista previa de la asignación automática según la jerarquía actual. Se confirma al lanzar la campaña.</div></div><div class="tw"><table class="de-t"><thead><tr><th>Evaluado</th><th>Evaluadores asignados</th></tr></thead><tbody>${c.participantes.filter(x=>rel(x)).map(id=>`<tr><td>${wc(id)}</td><td><div class="row">${pv.filter(x=>x.relId===id).map(x=>`<span class="pill">${TL[x.tipo]}${x.tipo==='Autoevaluación'?'':': '+esc(sn(x.evaluadorId))}</span>`).join('')||'<span class="pill warn">Sin evaluadores</span>'}</div></td></tr>`).join('')}</tbody></table></div>`}
  else{const fl=fs.filter(f=>!ui.de_fEst||(ui.de_fEst==='Vencida'?fVenc(f):f.estado===ui.de_fEst)).sort((a,b)=>relName(a.relId).localeCompare(relName(b.relId),'es'));const edit=adm&&c.estado==='En curso';
   b=`<div class="ph"><div class="row">${selH('de_fEst',['Pendiente',['Borrador','En borrador'],'Enviada','Vencida'],'Todos los estados')}<span class="muted num">${fl.length} formularios</span></div>${edit?`<button class="btn s" data-a="de_formAdd" data-id="${c.id}">Agregar evaluador</button>`:''}</div>
   ${fl.length?`<div class="tw"><table class="de-t"><thead><tr><th>Evaluado</th><th>Evaluador</th><th>Rol</th><th>Vence</th><th>Estado</th><th></th></tr></thead><tbody>${fl.map(f=>`<tr><td><b>${esc(relName(f.relId))}</b></td><td>${esc(relName(f.evaluadorId))}</td><td>${pill(TL[f.tipo])}</td><td class="num">${fd(f.vence)}</td><td>${fEstPill(f)}</td><td style="text-align:right;white-space:nowrap">${cal&&f.estado==='Enviada'?`<button class="btn s" data-a="de_formOpen" data-id="${f.id}">Ver</button> `:''}${edit&&f.estado!=='Enviada'&&f.tipo!=='Autoevaluación'?`<button class="btn s" data-a="de_formChg" data-id="${f.id}">Cambiar</button> `:''}${edit&&f.estado!=='Enviada'?`<button class="btn s d" data-a="de_formDel" data-id="${f.id}">Quitar</button>`:''}${edit&&f.estado==='Enviada'?`<button class="btn s" data-a="de_formReab" data-id="${f.id}">Devolver</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:emptyState('Ningún formulario coincide','Cambia el filtro de estado.')}`}}
 if(ui.de_cTab==='config')b=`<div class="pb"><dl><div><dt>Tipo</dt><dd>${esc(c.tipo)} · ${TDESC[c.tipo]}</dd></div><div><dt>Periodo</dt><dd class="num">${fd(c.desde)} – ${fd(c.hasta)}</dd></div><div><dt>Participantes</dt><dd>${c.participantes.length} personas</dd></div><div><dt>Peso en la nota</dt><dd>${ts.map(t=>TL[t]+' '+(+c.pesos[t]||0)+' %').join(' · ')}</dd></div></dl>
  <h3 style="margin:22px 0 10px">Competencias evaluadas</h3><div style="display:flex;flex-direction:column;gap:8px">${c.competencias.map(k=>`<div><b>${esc(comp(k).nombre)}</b> <span class="muted">· ${esc(comp(k).desc)}</span></div>`).join('')}</div>
  <h3 style="margin:22px 0 10px">Escala de ${c.escala.length} puntos</h3><div class="de-scale">${c.escala.map((l,i)=>`<label><input type="radio" disabled aria-label="${esc(l)}"><span><b>${i+1}</b><small>${esc(l)}</small></span></label>`).join('')}</div>
  <h3 style="margin:22px 0 10px">Preguntas abiertas</h3>${c.preguntas.length?`<ol style="margin:0;padding-left:20px;display:flex;flex-direction:column;gap:4px">${c.preguntas.map(q=>`<li>${esc(q.texto)}</li>`).join('')}</ol>`:'<p class="muted">Esta campaña no tiene preguntas abiertas.</p>'}
  ${c.estado!=='Borrador'?'<p class="muted" style="margin-top:18px">La configuración se bloquea al lanzar la campaña para que todos respondan el mismo formulario.</p>':''}</div>`;
 if(ui.de_cTab==='calib'){const rows=evs.map(e=>({e,k:calc(e)})),dist=[0,0,0];rows.forEach(x=>{const v=x.e.nota||x.k.nota;if(v)dist[v>=4?2:v>=3?1:0]++});const mx=Math.max(1,...dist),pc=evs.filter(e=>!e.nota&&calc(e).n).length;
  b=c.estado==='Borrador'?`<div class="pb">${emptyState('Aún no hay nada que calibrar','La calibración se habilita cuando cierras la recolección de respuestas.')}</div>`:
  `<div class="pb" style="display:flex;flex-direction:column;gap:14px">
   ${c.estado==='En curso'?'<div class="note">La campaña sigue abierta: estas notas son parciales. Para calibrar, usa «Cerrar y calibrar».</div>':c.estado==='Calibración'?`<div class="note">RRHH revisa las notas calculadas, las ajusta si corresponde y define el potencial. <b>El colaborador no ve nada hasta que se publique.</b>${cal&&pc?` <button class="btn s" data-a="de_calAceptar" data-id="${c.id}" style="margin-left:6px">Aceptar las ${pc} notas calculadas pendientes</button>`:''}</div>`:`<div class="note">Resultados publicados el ${fd(c.publicado)}. Cada colaborador ya puede ver el suyo en «Mis evaluaciones».</div>`}
   <div class="grid g4">${[['Por debajo (menos de 3)','warn'],['En lo esperado (3 a 3.9)','accent'],['Destacado (4 o más)','ok']].map((x,i)=>`<div><div class="de-kv"><span>${x[0]}</span><b class="num">${dist[i]}</b></div>${prog(dist[i]/mx*100,x[1])}</div>`).join('')}</div></div>
  <div class="tw"><table class="de-t"><thead><tr><th>Evaluado</th>${ts.map(t=>`<th>${TL[t]}</th>`).join('')}<th>Calculada</th><th>Nota final</th>${pot?'<th>Potencial</th>':''}<th></th></tr></thead><tbody>${rows.map(({e,k})=>`<tr><td>${wc(e.relId)}</td>${ts.map(t=>`<td class="num">${n1(k.por[t])}</td>`).join('')}<td class="num"><b>${n1(k.nota)}</b></td><td>${e.nota?notaPill(e.nota):k.n?'<span class="pill warn">Por calibrar</span>':'<span class="pill">Sin respuestas</span>'}</td>${pot?`<td>${e.potencial?pill(POT[e.potencial],e.potencial===3?'ok':e.potencial===2?'acc':''):'<span class="muted">—</span>'}</td>`:''}<td style="text-align:right;white-space:nowrap">${cal&&c.estado==='Calibración'&&k.n?`<button class="btn s" data-a="de_calibrar" data-id="${e.id}">Calibrar</button> `:''}${canSeeRes(e)&&k.n?`<button class="btn s" data-a="de_resOpen" data-id="${e.id}">Ver detalle</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
 return crumbs('de_eval','Evaluaciones',c.nombre)+`<div class="head"><div><h1>${esc(c.nombre)}</h1><div class="row" style="margin-top:6px">${cEstPill(c)}${pill('Evaluación '+c.tipo)}<span class="muted num">${fd(c.desde)} – ${fd(c.hasta)}</span></div></div><div class="row">${acc}</div></div>
 ${c.estado!=='Borrador'?`<div class="kpis">${kpi(evs.length,'Personas evaluadas')}${kpi(fs.length?Math.round(sent/fs.length*100)+' %':'—','Formularios enviados')}${kpi(fs.length-sent,'Por responder')}${kpi(venc,'Vencidos',venc?'crit':'')}</div>`:''}
 <div class="panel">${tabsH('de_cTab',tabs)}${b}</div>`}

function fbVisible(f){const m=mine();if(f.tipo==='Solicitud')return f.deId===m||f.paraId===m;if(f.privacidad==='Público')return true;if(f.deId===m||f.paraId===m)return true;
 if(f.privacidad==='Privado')return false;const r=rel(f.paraId);return !!r&&((m&&under(r,[m]))||(can('desempeno.resultados.ver')&&role().alcance==='todos'))}
const fbCard=f=>`<div class="de-card"><div class="row" style="justify-content:space-between"><div class="row">${chip(f.deId)}<span class="muted">→</span>${chip(f.paraId)}</div><div class="row">${f.tipo==='Reconocimiento'?pill('Reconocimiento'+(f.valor?' · '+f.valor:''),'ok'):pill('Feedback','acc')}${pill(f.privacidad==='Jefe'?'Lo ve también su jefe':f.privacidad)}<span class="mono muted">${fd(f.fecha)}</span></div></div><div>${esc(f.texto)}</div></div>`;

function vEvalForm(){const f=formOf(ui.de_form);if(!f)return gone('de_eval','Evaluaciones','El formulario ya no existe');const c=ciclo(f.cicloId),my=f.evaluadorId===mine();
 if(!my&&!can('desempeno.calibrar'))return deny();
 const r=rel(f.relId),ro=!my||f.estado==='Enviada'||c.estado!=='En curso',done=c.competencias.filter(k=>f.resp[k]).length;
 const fbs=col('de_feedback').filter(x=>x.tipo!=='Solicitud'&&x.paraId===f.relId&&x.fecha>=addDays(c.desde,-365)&&fbVisible(x)).slice(0,4);
 const objs=col('objetivos').filter(o=>o.relId===f.relId&&o.nivel==='Individual');
 return crumbs('de_eval','Evaluaciones',c.nombre)+`<div class="panel"><div class="pb"><div class="row" style="justify-content:space-between;align-items:flex-start"><div class="who"><span class="av xl">${esc(ini(nm(r)))}</span><div><div class="muted">${f.tipo==='Autoevaluación'?'Tu autoevaluación':'Estás evaluando a'}</div><h1>${esc(nm(r))}</h1><div class="muted">${esc(puesto(r.puestoId).nombre)}</div></div></div>
 <div class="row">${pill(TL[f.tipo],'acc')}${fEstPill(f)}<span class="muted num">Vence ${fd(f.vence)}</span></div></div>
 ${!my?`<div class="note" style="margin-top:14px">Vista de solo lectura para calibración. Respondió: <b>${esc(relName(f.evaluadorId))}</b>.</div>`:f.tipo==='Par'||f.tipo==='Subordinado'?'<div class="note" style="margin-top:14px">Tus respuestas se muestran a la persona evaluada <b>agrupadas y sin tu nombre</b>. Recursos Humanos sí puede verlas para la calibración.</div>':''}</div></div>
 ${(fbs.length||objs.length)&&f.tipo!=='Autoevaluación'?`<div class="grid g2">${objs.length?`<div class="panel"><div class="ph"><h2>Sus objetivos del periodo</h2></div><div class="pb" style="display:flex;flex-direction:column;gap:10px">${objs.map(o=>`<div><div class="de-kv"><span>${esc(o.titulo)}</span><b class="num">${Math.round(o.avance)} %</b></div>${prog(o.avance)}</div>`).join('')}</div></div>`:''}${fbs.length?`<div class="panel"><div class="ph"><h2>Feedback que recibió</h2><span class="muted">Solo el que tú puedes ver</span></div>${fbs.map(fbCard).join('')}</div>`:''}</div>`:''}
 <div class="panel"><div class="ph"><h2>Competencias</h2><span class="muted num" id="de_fprog">${done} de ${c.competencias.length} calificadas</span></div><div class="pb">${c.competencias.map(k=>`<div class="de-q"><div><b>${esc(comp(k).nombre)}</b><div class="muted">${esc(comp(k).desc)}</div></div>
  <div class="de-scale" role="radiogroup" aria-label="${esc(comp(k).nombre)}">${c.escala.map((l,i)=>`<label><input type="radio" name="de_r_${k}" value="${i+1}" data-defr="${k}"${f.resp[k]===i+1?' checked':''}${ro?' disabled':''}><span><b>${i+1}</b><small>${esc(l)}</small></span></label>`).join('')}</div>
  ${ro?(f.coms[k]?`<div class="muted">«${esc(f.coms[k])}»</div>`:''):`<textarea class="in" rows="2" data-deft="c:${k}" placeholder="Ejemplo o comentario (opcional)" aria-label="Comentario sobre ${esc(comp(k).nombre)}">${esc(f.coms[k]||'')}</textarea>`}</div>`).join('')}</div></div>
 <div class="panel"><div class="ph"><h2>Preguntas abiertas</h2></div><div class="pb" style="display:flex;flex-direction:column;gap:14px">${c.preguntas.map(q=>`<label style="display:flex;flex-direction:column;gap:5px;font-weight:600">${esc(q.texto)}${ro?`<span style="font-weight:400">${f.abiertas[q.id]?esc(f.abiertas[q.id]):'<span class="muted">Sin respuesta</span>'}</span>`:`<textarea class="in" rows="3" data-deft="a:${q.id}" style="font-weight:400">${esc(f.abiertas[q.id]||'')}</textarea>`}</label>`).join('')}
  <label style="display:flex;flex-direction:column;gap:5px;font-weight:600">Comentario general${ro?`<span style="font-weight:400">${f.comentario?esc(f.comentario):'<span class="muted">Sin comentario</span>'}</span>`:`<textarea class="in" rows="3" data-deft="g:" style="font-weight:400">${esc(f.comentario||'')}</textarea>`}</label></div>
 ${ro?'':`<div class="ph" style="border-top:1px solid var(--line);border-bottom:0"><span class="muted">El borrador se guarda solo mientras respondes.</span><div class="row"><button class="btn" data-a="de_formSave">Guardar y salir</button><button class="btn p" data-a="de_formSend">Enviar evaluación</button></div></div>`}</div>`}
function grabForm(){const f=formOf(ui.de_form);if(!f||f.evaluadorId!==mine()||f.estado==='Enviada')return null;
 document.querySelectorAll('[data-deft]').forEach(e=>{const [t,k]=e.dataset.deft.split(':'),v=e.value.trim();if(t==='c')f.coms[k]=v;else if(t==='a')f.abiertas[k]=v;else f.comentario=v});
 document.querySelectorAll('[data-defr]:checked').forEach(e=>f.resp[e.dataset.defr]=+e.value);
 if(f.estado==='Pendiente'&&(Object.keys(f.resp).length||f.comentario))f.estado='Borrador';syncEval(col('evaluaciones').find(e=>e.id===f.evalId));return f}

function vRes(){const ev=col('evaluaciones').find(e=>e.id===ui.de_res);if(!ev||!canSeeRes(ev))return gone('de_eval','Evaluaciones','Este resultado no está disponible');
 const c=ciclo(ev.cicloId),r=rel(ev.relId),self=ev.relId===mine(),k=calc(ev),fs=col('de_evalForms').filter(f=>f.evalId===ev.id&&f.estado==='Enviada');
 let grp={};fs.forEach(f=>(grp[f.tipo]=grp[f.tipo]||[]).push(f));let hidden=false;
 if(self){const an=[...(grp.Par||[]),...(grp.Subordinado||[])];if(((grp.Par||[]).length&&grp.Par.length<2)||((grp.Subordinado||[]).length&&grp.Subordinado.length<2)){delete grp.Par;delete grp.Subordinado;if(an.length>=2)grp['Pares y reportes']=an;else if(an.length)hidden=true}}
 const gl=Object.keys(grp),lab=t=>TL[t]||t,sc=(t,cid)=>{const v=grp[t].map(f=>f.resp[cid]).filter(Boolean);return v.length?avg(v)/c.escala.length*5:0};
 const low=c.competencias.map(cid=>({cid,v:avg(gl.filter(t=>t!=='Autoevaluación').map(t=>sc(t,cid)).filter(Boolean))})).filter(x=>x.v).sort((a,b)=>a.v-b.v)[0];
 const coms=[];fs.forEach(f=>{const who=f.tipo==='Jefe'?'Jefe directo':f.tipo==='Autoevaluación'?'Autoevaluación':self&&hidden?null:'Anónimo ('+(self&&grp['Pares y reportes']?'pares y reportes':TL[f.tipo].toLowerCase())+')';if(!who)return;
  c.preguntas.forEach(q=>{if(f.abiertas[q.id])coms.push([who,q.texto,f.abiertas[q.id]])});if(f.comentario)coms.push([who,'Comentario general',f.comentario])});
 const fbs=col('de_feedback').filter(x=>x.tipo!=='Solicitud'&&x.paraId===ev.relId&&x.fecha>=c.desde&&x.fecha<=addDays(c.hasta,60)&&fbVisible(x));
 const pdi=col('de_pdis').find(p=>p.evalId===ev.id),showPot=!self&&(can('desempeno.calibrar')||can('talento.ninebox.ver'));
 return crumbs('de_eval','Evaluaciones',c.nombre+' · '+nm(r))+`<div class="panel"><div class="pb"><div class="row" style="justify-content:space-between;align-items:flex-start"><div class="who"><span class="av xl">${esc(ini(nm(r)))}</span><div><h1>${esc(nm(r))}</h1><div class="muted">${esc(puesto(r.puestoId).nombre)} · ${esc(c.nombre)}</div><div class="row" style="margin-top:6px">${pill(ev.estado,ev.estado==='Publicada'?'ok':'warn')}${ev.leido?pill('Leído por el colaborador el '+fd(ev.leido)):''}</div></div></div>
  <div style="text-align:right"><div class="muted">Nota final</div><div style="font-family:var(--f-display);font-size:38px;line-height:1" class="num">${n1(ev.nota||k.nota)}<span class="muted" style="font-size:16px"> / 5</span></div>${!ev.nota?'<span class="pill warn">Calculada, sin calibrar</span>':''}${showPot&&ev.potencial?`<div style="margin-top:6px">${pill('Potencial '+POT[ev.potencial].toLowerCase(),ev.potencial===3?'ok':'acc')}</div>`:''}</div></div>
  ${ev.comentario?`<div class="note" style="margin-top:14px"><b>Mensaje de cierre:</b> ${esc(ev.comentario)}</div>`:''}${hidden?'<div class="muted" style="margin-top:10px">Las respuestas de pares y reportes se ocultan para proteger el anonimato (menos de 2 respuestas).</div>':''}</div>
  <div class="ph" style="border-top:1px solid var(--line)"><h2>Resultado por competencia</h2><span class="muted">Escala convertida a 5 puntos</span></div>
  <div class="tw"><table class="de-t"><thead><tr><th>Competencia</th>${gl.map(t=>`<th>${lab(t)}${grp[t].length>1?' ('+grp[t].length+')':''}</th>`).join('')}</tr></thead><tbody>${c.competencias.map(cid=>`<tr><td><b>${esc(comp(cid).nombre)}</b></td>${gl.map(t=>{const v=sc(t,cid);return `<td style="min-width:110px"><div class="row" style="flex-wrap:nowrap"><span class="num" style="width:26px">${n1(v)}</span><div style="flex:1">${prog(v/5*100,t==='Autoevaluación'?'muted':'')}</div></div></td>`}).join('')}</tr>`).join('')}</tbody></table></div></div>
 <div class="grid g2"><div class="panel"><div class="ph"><h2>Comentarios</h2></div>${coms.length?coms.map(x=>`<div class="de-card"><div class="row">${pill(x[0])}<span class="muted">${esc(x[1])}</span></div><div>${esc(x[2])}</div></div>`).join(''):'<div class="pb muted">Nadie dejó comentarios escritos.</div>'}</div>
 <div style="display:flex;flex-direction:column;gap:14px"><div class="panel"><div class="ph"><h2>Feedback del periodo</h2></div>${fbs.length?fbs.map(fbCard).join(''):'<div class="pb muted">Sin feedback registrado en el periodo.</div>'}</div>
 <div class="panel"><div class="ph"><h2>Siguiente paso</h2></div><div class="pb" style="display:flex;flex-direction:column;gap:10px">${low?`<div>La competencia con menor puntaje es <b>${esc(comp(low.cid).nombre)}</b> (${n1(low.v)}). Es un buen punto de partida para conversar; la decisión de qué desarrollar es de la persona y su jefe.</div>`:''}
  ${pdi?`<div><button class="btn" data-a="de_pdiOpen" data-id="${pdi.id}">Ver plan de desarrollo</button></div>`:low&&(self||can('desarrollo.planes.administrar'))&&ev.estado==='Publicada'?`<div><button class="btn p" data-a="de_pdiNew" data-rel="${ev.relId}" data-comp="${low.cid}" data-ev="${ev.id}">Crear plan de desarrollo</button></div>`:''}
  ${self&&!ev.leido?`<div><button class="btn" data-a="de_resLeido" data-id="${ev.id}">Confirmar que leí mi resultado</button></div>`:''}</div></div></div></div>`}
