 de_cicloRec:d=>{const c=ciclo(d.id),n=new Set(formsDe(c.id).filter(f=>f.estado!=='Enviada').map(f=>f.evaluadorId)).size;if(!n)return toast('Nadie tiene formularios pendientes');
  (c.recordatorios=c.recordatorios||[]).push({fecha:TODAY,n,por:me().nombre});simMsg(n+' evaluadores','Recordatorio: tienes evaluaciones por responder en «'+c.nombre+'»');log('Recordatorio (simulado)','Campaña de evaluación',c.nombre,c.id,'',n+' personas');save();render();toast('Recordatorio registrado para '+n+' personas (simulado)')},
