const PREP=['Listo ahora','1 año','2 años','En desarrollo'];
const pdiOf=id=>col('de_pdis').find(p=>p.id===id);
const pdiVis=p=>p.relId===mine()||(can('desarrollo.planes.administrar')&&inSc(p.relId));
const insDe=(relId,cursoId)=>(T().inscripciones||[]).find(i=>i.relId===relId&&i.cursoId===cursoId);
const accEst=(a,p)=>{if(a.tipo==='Curso'&&a.cursoId){const i=insDe(p.relId,a.cursoId);if(i&&i.estado==='Completado')return 'Hecha';if(i&&i.estado==='En progreso'&&a.estado==='Pendiente')return 'En curso'}return a.estado};
const pdiProg=p=>p.acciones.length?p.acciones.filter(a=>accEst(a,p)==='Hecha').length/p.acciones.length*100:0;
const lastEval=relId=>{const e=col('evaluaciones').filter(e=>e.relId===relId&&e.nota&&e.estado==='Publicada').sort((a,b)=>((ciclo(b.cicloId)||{}).hasta||'').localeCompare((ciclo(a.cicloId)||{}).hasta||''));return e[0]||null};
function riesgo(r){const f=[],hs=T().historial.filter(h=>h.relId===r.id),ult=c=>hs.filter(h=>h.campo===c).map(h=>h.fecha).sort().pop()||r.ingreso;
 const ap=days(ult('puestoId'),TODAY)/365;if(ap>=4&&!['Dirección','Gerencia'].includes(puesto(r.puestoId).nivel))f.push({t:'Mucho tiempo en el mismo puesto',d:`Lleva ${ap.toFixed(1)} años como ${puesto(r.puestoId).nombre} sin cambio de puesto.`});
 if(can('colaborador.salario.ver')){const m=Math.floor(days(ult('salario'),TODAY)/30.4);if(m>=18)f.push({t:'Sin aumento reciente',d:`Su sueldo no cambia hace ${m} meses.`});
  const b=(T().de_bandas||[]).find(x=>x.puestoId===r.puestoId&&x.moneda===cur(r));if(b&&r.salario&&r.salario<b.min)f.push({t:'Sueldo por debajo de su banda',d:'Gana menos que el mínimo de la banda salarial de su puesto.'})}
 if(r.contratoFin){const d=days(TODAY,r.contratoFin);if(d<=60)f.push({t:'Contrato por vencer',d:d<0?'Su contrato a plazo venció y no se ha renovado.':`Su contrato ${r.contratoTipo.toLowerCase()} vence en ${d} días y no hay renovación registrada.`})}
 const e=lastEval(r.id);if(e&&e.nota>=4.5&&!col('de_pdis').some(p=>p.relId===r.id&&p.estado==='En curso'))f.push({t:'Desempeño sobresaliente sin plan de desarrollo',d:`Obtuvo ${n1(e.nota)} en su última evaluación y no tiene un plan de desarrollo activo.`});
 if(r.jefeId&&col('de_unos').some(u=>u.jefeId===r.jefeId&&u.estado==='Realizada')){const l=col('de_unos').filter(u=>u.relId===r.id&&u.estado==='Realizada').map(u=>u.fecha).sort().pop();if(!l||days(l,TODAY)>60)f.push({t:'Sin reuniones 1:1 recientes',d:l?`Su última reunión 1:1 registrada fue hace ${days(l,TODAY)} días.`:'Su jefe hace reuniones 1:1 con otras personas del equipo, pero no tiene ninguna registrada con ella.'})}
 const cl=(T().encRespuestas||[]).filter(x=>x.relId===r.id).flatMap(x=>Object.values(x.valores||{}).filter(v=>typeof v==='number'&&v<=5));if(cl.length&&avg(cl)<=2.5)f.push({t:'Baja nota de clima',d:`En encuestas no anónimas promedió ${avg(cl).toFixed(1)} de 5.`});
 return f}
