  fields:[...(p?[]:[{k:'relId',l:'Persona',opts:ops,req:1,dyn:1}]),{k:'propuesto',l:'Nuevo sueldo básico mensual ('+c.moneda+')',type:'number',req:1},{k:'motivo',l:'Motivo',opts:['Mérito por desempeño','Ajuste a la banda','Promoción','Retención','Equidad interna'],req:1},{k:'sustento',l:'Sustento con criterios objetivos',type:'textarea',req:1,full:1}],
