 de_igJustVer:d=>{const j=col('de_igJust').find(x=>x.id===d.id),c=col('de_igCats').find(x=>x.id===j.catId)||{};openModal('Justificación · '+(c.nombre||''),`<dl><div><dt>Brecha al registrarla</dt><dd>${Math.abs(j.brecha).toFixed(1)} % ${j.brecha>0?'a favor de hombres':'a favor de mujeres'}</dd></div><div><dt>Registrada</dt><dd>${fd(j.fecha)} · ${esc(j.autor)}</dd></div></dl><h3 style="margin:16px 0 8px">Criterios objetivos</h3><div class="row">${j.criterios.map(x=>pill(x,'acc')).join('')}</div><h3 style="margin:16px 0 8px">Sustento</h3><p>${esc(j.detalle)}</p>${j.plan?`<h3 style="margin:16px 0 8px">Acción correctiva</h3><p>${esc(j.plan)}</p>`:''}`)},
 de_igCsv:()=>{const mon=ui.de_igMon;csvModal('Reporte de brecha salarial · '+mon,[['Categoría','Mujeres','Hombres','Promedio mujeres','Promedio hombres','Brecha %','Situación','Criterios de justificación'],...col('de_igCats').map(c=>brechaCat(c,mon)).filter(x=>x.rs.length).map(x=>[x.c.nombre,x.F.length,x.M.length,x.F.length?Math.round(x.aF):'',x.M.length?Math.round(x.aM):'',x.br===null?'':x.br.toFixed(1),x.est,x.j?x.j.criterios.join(' | '):''])],'Brecha salarial')},
