function elegible(b,r){const g=b.regla||{};return r.estado==='Activo'&&(!(g.empresas||[]).length||g.empresas.includes(r.empresaId))&&(!(g.niveles||[]).length||g.niveles.includes(puesto(r.puestoId).nivel))&&(!(g.contratos||[]).length||g.contratos.includes(r.contratoTipo))&&meses(r)>=(+g.minMeses||0)}
