function asigT(c,ac){const out=[],ts=TIPOS[c.tipo];c.participantes.forEach(id=>{const r=ac.find(x=>x.id===id);if(!r)return;
 if(ts.includes('Autoevaluación'))out.push({relId:id,evaluadorId:id,tipo:'Autoevaluación'});
 if(ts.includes('Jefe')&&ac.some(x=>x.id===r.jefeId))out.push({relId:id,evaluadorId:r.jefeId,tipo:'Jefe'});
 if(ts.includes('Par')&&r.jefeId)ac.filter(x=>x.jefeId===r.jefeId&&x.id!==id).slice(0,2).forEach(x=>out.push({relId:id,evaluadorId:x.id,tipo:'Par'}));
 if(ts.includes('Subordinado'))ac.filter(x=>x.jefeId===id).slice(0,3).forEach(x=>out.push({relId:id,evaluadorId:x.id,tipo:'Subordinado'}))});return out}
