 CU('dcu1','Inducción a Grupo Andino','Inducción','Quiénes somos, cómo trabajamos y qué puedes esperar en tus primeras semanas.',2,15,0,'Recursos Humanos',[
  ['Bienvenida y nuestra historia','Texto','Grupo Andino nació en Lima como una empresa de servicios y hoy reúne tres razones sociales en Perú y Colombia.\nNuestro propósito es que cada cliente reciba lo que pidió, cuando lo pidió. Todo lo demás (procesos, sistemas, indicadores) existe para cumplir esa promesa.\nEn tus primeras semanas conocerás a tu equipo, tus herramientas y los objetivos de tu área.'],
  ['Mensaje de la Gerencia General','Video','Rosa Quispe, gerente general, explica las prioridades del año y lo que espera de cada persona que se suma al grupo.',6],
  ['Reglamento interno de trabajo','PDF','Lee el reglamento completo. Los puntos que más consultas generan: horarios y tolerancias, uso de equipos de la empresa, permisos y canal de consultas a Recursos Humanos.',15,'Reglamento Interno de Trabajo 2026.pdf'],
  ['Tus primeros 30 días','Texto','Semana 1: accesos, equipo y conocer a tu jefe y a tu compañero guía.\nSemanas 2 y 3: capacitaciones obligatorias (seguridad y salud, prevención del hostigamiento) y tus primeras tareas acompañadas.\nSemana 4: primera reunión 1:1 con tu jefe para acordar tus objetivos.']],
  [['¿Cuál es el propósito que guía el trabajo en Grupo Andino?',['Vender más que el año anterior','Que cada cliente reciba lo que pidió, cuando lo pidió','Tener la mayor cantidad de sedes'],1],['¿Qué ocurre en tu cuarta semana?',['La evaluación anual','Tu primera reunión 1:1 para acordar objetivos','La entrega de uniformes'],1],['¿Dónde encuentras las reglas sobre horarios y permisos?',['En el reglamento interno de trabajo','En el contrato de alquiler de la sede','En el manual de marca'],0]]);
 CU('dcu2','Seguridad y salud en el trabajo: inducción general','Seguridad y salud','Riesgos de tu puesto, cómo reportar un incidente y qué hacer en una emergencia. Obligatorio por la Ley 29783.',4,30,12,'Prevención Andina S.A.C.',[
  ['Derechos y obligaciones en seguridad y salud','Texto','La Ley 29783 obliga al empleador a prevenir los riesgos y al trabajador a cumplir las normas de seguridad y a usar los equipos de protección.\nTienes derecho a ser informado de los riesgos de tu puesto, a recibir capacitación y a paralizar una tarea si existe peligro inminente.\nEl Comité de Seguridad y Salud representa a los trabajadores: conoce quiénes lo integran en tu sede.'],
  ['Identificación de peligros y evaluación de riesgos','Video','Cómo leer la matriz de riesgos de tu puesto y reconocer los peligros más frecuentes en oficina y en almacén.',12],
  ['Cómo reportar un incidente o accidente','Texto','Todo accidente, incidente o condición insegura se reporta el mismo día a tu jefe y a Seguridad y Salud.\nUn incidente sin lesión también se reporta: es la oportunidad de corregir antes de que alguien se lastime.\nNunca muevas a una persona lesionada salvo que su vida corra peligro; llama a la brigada.'],
  ['Plan de respuesta ante emergencias','PDF','Ubica las rutas de evacuación, las zonas seguras y los extintores de tu sede. Participa en los simulacros.',10,'Plan de respuesta ante emergencias.pdf']],
  [['Si ocurre un incidente sin lesiones, ¿qué corresponde?',['No reportarlo porque nadie se lastimó','Reportarlo el mismo día','Esperar a la reunión mensual'],1],['¿Qué puedes hacer ante un peligro inminente?',['Seguir trabajando con cuidado','Paralizar la tarea y avisar','Pedir un permiso por escrito'],1],['¿Quién representa a los trabajadores en temas de seguridad y salud?',['El Comité de Seguridad y Salud','El área de ventas','El proveedor de limpieza'],0],['¿Qué norma regula la seguridad y salud en el trabajo en el Perú?',['Ley 29783','Ley 30709','Ley 27942'],0]]);
 CU('dcu3','Prevención del hostigamiento sexual laboral','Cumplimiento','Qué es el hostigamiento sexual, cómo se denuncia y qué medidas de protección existen. Obligatorio por la Ley 27942.',2,30,12,'Estudio Laboral Rímac',[
  ['Qué es y qué no es hostigamiento sexual','Texto','Es una conducta de naturaleza o connotación sexual o sexista no deseada por la persona contra la que se dirige. No requiere que se repita ni que exista rechazo expreso.\nPuede darse entre jefes y subordinados, entre compañeros, o con clientes y proveedores, dentro o fuera del centro de trabajo.\nEjemplos: comentarios sobre el cuerpo, bromas sexistas, mensajes insistentes, contacto físico no deseado, promesas o amenazas a cambio de favores.'],
  ['Cómo presentar una queja y qué pasa después','Texto','Puedes presentar tu queja ante Recursos Humanos o por el canal de denuncias, de forma verbal o escrita.\nEn un máximo de tres días hábiles se dictan medidas de protección para la persona afectada, como la rotación del presunto hostigador o la suspensión temporal.\nEl Comité de Intervención investiga y emite su informe; la empresa decide la sanción. Toda la información es confidencial.'],
  ['Casos para reflexionar','Video','Tres situaciones cotidianas analizadas por una especialista: cuándo una broma deja de serlo y cómo actuar si eres testigo.',10]],
  [['¿Hace falta que la conducta se repita para ser hostigamiento sexual?',['Sí, al menos tres veces','No, basta una sola conducta','Solo si hay testigos'],1],['¿En qué plazo se dictan las medidas de protección?',['Máximo tres días hábiles','Treinta días','Cuando termine la investigación'],0],['Si eres testigo de una situación de hostigamiento, ¿qué es lo correcto?',['No intervenir porque no es tu asunto','Apoyar a la persona afectada e informar por los canales','Comentarlo en el grupo del área'],1]]);
 CU('dcu4','Excel para análisis de datos','Herramientas','Tablas dinámicas, búsquedas y gráficos para preparar reportes confiables.',12,0,0,'Instituto Datos Perú',[
  ['Ordenar los datos antes de analizar','Texto','Un buen análisis empieza con una tabla limpia: una fila por registro, una columna por dato y sin celdas combinadas.\nConvierte tu rango en Tabla para que las fórmulas y los gráficos crezcan solos cuando agregues filas.'],
  ['Tablas dinámicas paso a paso','Video','Resume miles de filas en segundos: filas, columnas, valores y filtros.',18],
  ['Búsquedas con BUSCARX','Texto','BUSCARX reemplaza a BUSCARV: busca hacia cualquier lado y te deja definir qué mostrar cuando no encuentra el valor.\nEjemplo: traer el centro de costo de cada colaborador desde la tabla de puestos.']],
  [['¿Qué conviene hacer antes de crear una tabla dinámica?',['Combinar celdas del encabezado','Tener una fila por registro y una columna por dato','Ocultar las columnas vacías'],1],['¿Qué ventaja tiene BUSCARX frente a BUSCARV?',['Solo funciona con números','Busca en cualquier dirección y maneja valores no encontrados','No necesita datos'],1]]);
 CU('dcu5','Liderazgo para nuevos jefes','Liderazgo','De hacer a lograr que otros hagan: delegar, dar feedback y conducir reuniones 1:1.',16,0,0,'Escuela de Líderes del Sur',[
  ['El cambio de rol','Texto','Como jefe, tu resultado ya no es tu trabajo individual: es el resultado de tu equipo.\nLos tres errores más comunes del primer año son seguir haciendo el trabajo técnico, evitar las conversaciones difíciles y no pedir ayuda.'],
  ['Delegar con claridad','Texto','Delegar no es soltar: acuerda el resultado esperado, la fecha, el nivel de autonomía y cómo harán seguimiento.\nDelega primero lo que desarrolla a la otra persona, no solo lo que te quita tiempo.'],
  ['Reuniones 1:1 que sirven','Video','Cómo preparar la agenda con tu colaborador, qué preguntar y cómo cerrar con compromisos.',14],
  ['Guía de feedback','PDF','Modelo situación, conducta e impacto, con ejemplos para reconocer y para corregir.',10,'Guía de feedback efectivo.pdf']],
  [['¿Cuál es el resultado principal de un jefe?',['Su trabajo individual','El resultado de su equipo','La cantidad de reuniones'],1],['Al delegar, ¿qué se debe acordar?',['Solo la fecha','Resultado esperado, fecha, autonomía y seguimiento','Nada, para dar libertad'],1],['¿Qué se delega primero?',['Lo que desarrolla a la otra persona','Lo que nadie quiere hacer','Lo urgente de última hora'],0]]);
 CU('dcu6','Fundamentos de JavaScript moderno','Tecnología','Funciones, promesas, manejo de errores y pruebas para escribir código mantenible.',20,0,0,'Interno · Carlos Pérez',[
  ['Funciones y alcance de variables','Texto','Declara con const por defecto y con let solo cuando el valor cambie. Evita var.\nUna función debe hacer una sola cosa y su nombre debe decir cuál. Si necesitas un comentario para explicar qué hace, probablemente deba dividirse.'],
  ['Promesas y async/await','Video','Cómo encadenar operaciones asíncronas y evitar el «infierno de callbacks».',16],
  ['Manejo de errores','Texto','Captura los errores donde puedas hacer algo útil con ellos; no los silencies.\nUn mensaje de error debe decir qué pasó y qué puede hacer la persona para resolverlo.'],
  ['Pruebas unitarias','Texto','Una prueba verifica un comportamiento, no una implementación. Empieza por los casos que más duelen cuando fallan.\nSi una función es difícil de probar, suele ser señal de que hace demasiadas cosas.']],
  [['¿Qué declaración se recomienda usar por defecto?',['var','const','let'],1],['¿Dónde conviene capturar un error?',['Donde se pueda hacer algo útil con él','En todas las funciones','Nunca, para no ocultarlo'],0],['¿Qué verifica una buena prueba unitaria?',['La implementación interna','Un comportamiento','El estilo del código'],1]]);
 CU('dcu7','Técnicas de negociación comercial','Comercial','Preparar la negociación, manejar objeciones y cerrar cuidando el margen.',12,0,0,'Consultora Cierre',[
  ['Preparación: intereses y alternativas','Texto','Antes de sentarte define tu objetivo, tu límite y tu mejor alternativa si no hay acuerdo.\nInvestiga qué necesita realmente el cliente: el precio suele ser solo una parte.'],
  ['Manejo de objeciones','Video','Las cinco objeciones más comunes y cómo responderlas sin regalar margen.',12],
  ['El cierre','Texto','Resume lo acordado, confirma los siguientes pasos con fecha y responsable, y envía el resumen el mismo día.']],
  [['¿Qué debes definir antes de negociar?',['Solo el precio de lista','Objetivo, límite y mejor alternativa','El descuento máximo de la competencia'],1],['¿Qué se hace al cerrar?',['Resumir lo acordado y fijar los siguientes pasos','Esperar a que el cliente escriba','Ofrecer un descuento adicional'],0]]);
 let k=0;const I=(cursoId,relId,estado,vence,nLec,extra)=>{const c=t.cursos.find(x=>x.id===cursoId),done=estado==='Completado';t.inscripciones.push({id:'din'+(++k),cursoId,relId,estado,vence,asignado:extra&&extra.asig||D(-25),asignadoPor:'Carmen Huamán Rojas',origen:(extra&&extra.origen)||(c.obligatorio?'Toda la organización':'Individual'),lecciones:done?c.lecciones.map(l=>l.id):c.lecciones.slice(0,nLec||0).map(l=>l.id),intentos:done?[{fecha:extra.comp,nota:extra.nota,aprobado:true}]:[],...(done?{completado:extra.comp,nota:extra.nota,cert:'AYN-'+extra.comp.slice(0,4)+'-'+String(k).padStart(5,'0'),inicio:extra.comp,...(c.vigenciaMeses?{validoHasta:addDays(extra.comp,365)}:{})}:{})})};
